"""Render the source-note study from reviewed outputs and measured token counts."""
import json,hashlib
from pathlib import Path
from html import escape as e
from site_navigation import project_tabs,experiment_subtabs
from build_answering_results import CSS,details,table as raw_table,text,link
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'research/notes-optimization'
NAMES={'reactive':'Reactive','legacy_all':'Old notes · all snapshots','legacy_latest':'Old notes · latest snapshot','legacy':'Old notes','snapshot':'Compact replacement','delta':'Incremental edits','events':'Event fields','evidence':'Source excerpts with event labels','linked':'Source notes','reactive_guided':'Reactive + focused prompt','linked_guided':'Source notes + focused prompt','events_guided':'Event fields + focused prompt','delta_guided':'Edits + focused prompt','snapshot_guided':'Replacement + focused prompt'}
STAGES={'event_reader':'Development · event-field Thinking reader','source_reader_development':'Development · source-note Thinking reader','development':'Initial prompts','development_v2':'Revised prompts','development_v3':'Corrected edit controller','event_fields':'Event fields','evidence_index':'Source excerpts with event labels','linked_a100_loopback':'Source selection','linked_context':'Selected design · development','additional_writer':'Additional meetings · Instruct','additional_reader':'Additional meetings · Thinking','parakeet_writer':'Parakeet · Instruct','parakeet_reader':'Parakeet · Thinking','whisper_writer':'Whisper · Instruct','whisper_reader':'Whisper · Thinking'}
def fmt(x):return 'Unexposed' if x is None else f'{x:,.0f}'
def score(r):return str(r['complete'])+'/'+str(r['questions']) if r['reviewed']==r['questions'] else 'Review pending'
def main():
 number=0
 def table(caption,heads,rows):
  nonlocal number
  number+=1;return raw_table(number,caption,heads,rows)
 d=json.loads((P/'results.json').read_text());pr=json.loads((P/'prompts.json').read_text());sel=d['selection'];findings=json.loads((P/'findings.json').read_text()) if (P/'findings.json').exists() else []
 if not findings:findings=[dict(text='Source notes store original speech once and link later changes to earlier evidence.',url='#design'),dict(text='The selected writer reduced earlier generated tokens by 62% on the six development questions.',url='#development'),dict(text='Twelve additional questions test answer quality and request-time thinking with frozen notes and prompts.',url='#results'),dict(text='Automatic-transcript and event-change checks test source selection under recognition errors and changing plans.',url='#asr')]
 body='<header class="hero"><p class="small">4 November 2026 · Structured-note optimization</p><h1>Compact notes that track meeting changes</h1></header><section id="findings"><h2>Main findings</h2><ul>'+''.join('<li>'+e(x['text'])+' '+link(x['url'],'Evidence')+'</li>' for x in findings)+'</ul><p class="small">'+link('../todo.html','Project checklist')+' · '+link('../daily-log.html','Daily log')+' · '+link('answering-results.html#s2-tradeoff','Earlier S2 results')+'</p></section>'
 body+='<section id="design"><h2>1. Source notes and event changes</h2><p>The model selects useful transcript segments and links related statements. The program copies the selected words, speaker labels and source times into one bounded note state. The next update receives the new speech and the current state. At question time, the reader receives the full available transcript and the latest notes.</p>'
 body+=table('Inputs and outputs of the selected system.', ['Module','Input','Output'],[['Transcript boundary','Existing 25–40 s boundaries, within the requested 10–40 s range.','Newly available transcript segments; the original schedule is shared across conditions.'],['Source selector','New transcript, up to ten seconds of earlier reference speech and one note state.','Source IDs, categories, priorities and links; no generated factual prose.'],['Context and revision checks','Selected segments, nearby past speech and proposed revision links.','Program-copied neighboring speech; the same model checks each proposed revision in a separate short call.'],['Note store','Accepted sources and relationships.','At most 64 source segments, 20 visible links and 4,096 compact-JSON tokens; full source and link history remains on disk.'],['Question-time reader','Full transcript, latest note state and the user question.','Brief answer, source IDs and any missing information; Thinking exposes its native reasoning-token count.']])
 body+='<p>A link can say <em>revises, confirms, explains, qualifies</em> or <em>refers to</em>. A revised deadline retains both the earlier and later statement. A different task keeps its own deadline. “I uploaded it” and “I cannot see it” remain separate claims until speech establishes what happened.</p><p>The selector skips greetings, routine acknowledgements and repeated facts without a change. Nearby source context helps preserve pronouns, unfinished clauses and qualifications. Exact source IDs are stored once per state; repeated speech in distinct source segments can still remain. The token limit removes lower-priority older sources first and favors recent revision endpoints.</p>'
 body+='<p><strong>Worked example:</strong> “Maya will prepare the sensor shipment. It should leave on Wednesday.” followed by “Change the sensor shipment to Thursday. Omar will handle it instead of Maya.” should retain the original assignment and its revision; an invoice due Monday remains a separate task. These names and values occur in a control test after the design was frozen.</p></section>'
 body+='<section id="protocol"><h2>2. Matched comparison</h2><ul><li>Use six development questions from five meetings, then freeze the policy before twelve additional questions from six other meetings.</li><li>Generate the additional-meeting notes with Qwen3-30B-A3B-Instruct-2507 and reuse identical notes for both Instruct and Thinking readers.</li><li>Keep the full transcript and the original answer prompt; test a focused reader instruction both with and without notes.</li><li>Use greedy Instruct decoding and two Qwen3-30B-A3B-Thinking-2507 request seeds, 23 and 47.</li><li>Keep each note update question-blind and count all earlier writer and revision-check work.</li></ul>'
 body+=table('Five conditions on the twelve additional questions.', ['Condition','Question-time input','Earlier model work'],[['Reactive','Full transcript + question.','None.'],['Old notes','Full transcript + question + all accumulated structured snapshots.','Original full-prefix and earlier-snapshot prompting, rerun with the same Instruct writer.'],['Source notes','Full transcript + question + one selected source-note state.','Incremental source selection, context copying and revision checks.'],['Reactive + focused prompt','Reactive input + the focused reader instruction.','None.'],['Source notes + focused prompt','Source-note input + the same focused reader instruction.','The same saved source-note run.']])
 body+='<p>This study reviews 570 generated answers across 18 distinct questions and 11 meetings; repeated conditions and seeds account for the larger output count.</p><p><strong>Scoring:</strong> Codex compares the final answer with previously reviewed required facts and source evidence. A complete answer contains the required facts and no material unsupported factual claim. Partial answers, incorrect answers and empty answers are retained. Citation format, source-ID validity and note-schema validity are audited separately. Additional-meeting answer packets hide the model and condition during review; this is not an independent human assessment.</p><p>The office-headcount reference was corrected from eighteen to fifteen after reviewing the later distinction between eighteen positions and fifteen people. The LCD-chip reference now includes an earlier statement that it is more expensive, while the amount remains unknown. The remote-control scope reference now retains the later TV-only backup and tentative reconsideration. Every condition uses the same corrected references; frozen model inputs and prompts are unchanged.</p><p>For the profit question, a bare 50% calculation is recorded as partially correct unless it retains the production-cost cap and before-other-costs qualification. The raw arithmetic and review reason remain visible.</p><p><strong>Token accounting:</strong> request-time thinking tokens are native reasoning tokens generated after the question. Earlier reasoning and note output are amortized-thinking costs. Instruct has no exposed native thinking channel. Total generated tokens include all earlier output, request-time reasoning, answer JSON and delimiters. Input tokens count the logical prompt size, including cached tokens. CPU copying generates no model tokens; copied text counts whenever it enters a later prompt. Writer work is counted once per meeting through its latest tested request, and the two reader seeds share the same saved notes.</p><p>Reader output limits are 2,048 tokens for Instruct and 16,384 for Thinking. The Instruct writer has a 2,048-token cap; revision checks have a 64-token cap. The model context is 65,536 tokens and no input is silently trimmed. The additional questions were selected by meeting split and request timing; they cover '+e(', '.join(d['additional_selection']['meetings']))+'.</p></section>'
 corrections=d.get('reference_corrections',{}).get('overrides',[])
 if corrections:body+=details('Full-prefix reference corrections',table('Reference corrections applied equally to every condition.', ['Question','Earlier reference','Current reference'],[[e(x['id']),e(x['previous_answer']),e(x['answer'])] for x in corrections])+'<p>'+link('../research/notes-optimization/reference-corrections.json','Source passages and correction reasons')+'</p>')
 body+='<section id="results"><h2>3. Additional-meeting results</h2>'
 for filename,title,caption in [('accuracy-thinking.svg','Figure 1. Accuracy and request-time thinking','Left: complete answers out of twelve. Right: mean native thinking tokens per request. Separate symbols show the two Thinking seeds; the Instruct reader has no native thinking channel.'),('total-token-cost.svg','Figure 2. Total token cost','Logical input tokens and generated tokens for the twelve-question set, averaged across the two Thinking request seeds. Earlier writer and checker work is included once per condition. Input and output token volumes are shown separately.')]:
  if (P/filename).exists():body+='<figure><div class="plot-scroll" tabindex="0"><img src="../research/notes-optimization/'+filename+'" alt="'+e(caption)+'" style="width:100%;height:auto;min-width:840px"></div><figcaption><strong>'+title+'.</strong> '+e(caption)+' '+link('../research/notes-optimization/'+filename.replace('.svg','.png'),'PNG')+' · '+link('../research/notes-optimization/'+filename.replace('.svg','.pdf'),'PDF')+'</figcaption></figure>'
 rows=[]
 for r in d['summaries']:
  if r['stage'] not in ['additional_writer','additional_reader'] or r['questions']!=12:continue
  rows.append([('Instruct' if r['model']=='instruct' else 'Thinking · '+str(r['seed'])),NAMES[r['policy']],score(r),fmt(r['mean_request_thinking_tokens']),fmt(r['mean_request_input_tokens']),fmt(r['earlier_generated_tokens']),fmt(r['total_generated_tokens'])])
 body+=table('Additional-meeting answer quality and token cost; totals cover twelve questions and the shared earlier work.', ['Reader','Condition','Complete / 12','Mean request thinking','Mean request input','Earlier generated','Total generated'],rows) if rows else '<p>The additional-meeting runs are in progress.</p>'
 if (P/'analysis-notes.json').exists():body+=''.join('<p>'+e(x)+'</p>' for x in json.loads((P/'analysis-notes.json').read_text()).get('additional',[]))
 office=[a for a in d['answers'] if a['stage']=='additional_reader' and a['seed']==23 and a['question_id']=='scale:IB4003-S075-Q3' and a['policy'] in ['reactive','legacy','linked']]
 if office:
  content='<p>The later source distinguishes fifteen people from eighteen positions. Source notes retain both the correction and its link to the earlier statement.</p>'
  for a in office:
   aid='answer-'+hashlib.sha256((a['job']+'|'+a['id']).encode()).hexdigest()[:12]
   content+='<p><strong>'+e(NAMES[a['policy']])+':</strong> '+e(a['answer'])+' '+link('#'+aid,'Complete evaluation case')+'</p>'
  body+=details('Example: an office count corrected during discussion',content)
 body+='</section><section id="asr"><h2>4. Existing automatic transcripts</h2><p>The same frozen source-note policy is tested on the original six questions using the existing Parakeet and Whisper transcripts and anonymous speaker labels. The question is supplied as text. Reference identities are mapped only for scoring; the model receives automatic labels. Transcript boundaries and recognition outputs are unchanged.</p>'
 rows=[]
 for method in ['parakeet','whisper']:
  for model in ['instruct','thinking']:
   for guided in [False,True]:
    suffix='_guided' if guided else '';groups=[]
    for policy in ['reactive'+suffix,'linked'+suffix]:
     rr=[r for r in d['summaries'] if r['stage'].startswith(method+'_') and r['model']==model and r['policy']==policy and r['questions']==6];groups.append(rr)
    if not any(groups):continue
    ss=lambda rs:'; '.join(('s'+str(r['seed'])+': ' if model=='thinking' else '')+score(r) for r in rs)
    tt=lambda rs:'; '.join(fmt(r['mean_request_thinking_tokens']) for r in rs) if model=='thinking' else 'Unexposed'
    rows.append([method.title(),model.title(),'Focused' if guided else 'Original',ss(groups[0]),ss(groups[1]),tt(groups[0])+' → '+tt(groups[1])])
 body+=table('Six-question automatic-transcript comparison; Thinking values list seeds 23 and 47 in that order.', ['Transcript','Reader','Prompt','Reactive complete','Source notes complete','Mean request thinking: reactive → notes'],rows) if rows else '<p>Automatic-transcript comparisons are in progress.</p>'
 if (P/'analysis-notes.json').exists():body+=''.join('<p>'+e(x)+'</p>' for x in json.loads((P/'analysis-notes.json').read_text()).get('asr',[]))
 body+='<p>'+link('answering-results.html#s2-asr','Original transcript-quality analysis and WER')+' · '+link('answering-results.html#implementation-details','Speaker labels and reference identity matching')+'</p></section>'
 body+='<section id="changes"><h2>5. Retaining event changes and limiting repetition</h2>'
 audit=d.get('integrity_audit')
 if audit:
  body+='<p>'+e(audit.get('summary',''))+'</p>'
  rows=[[e(x['test']),e(x['result']),e(x['evidence'])] for x in audit.get('controls',[])];body+=table('Authored event trajectories use names and values absent from the prompt example; these checks are separate from AMI answer accuracy.', ['Test','Result','Evidence'],rows) if rows else ''
  body+=details('Control trajectories and source-integrity checks','<pre>'+e(json.dumps(audit,ensure_ascii=False,indent=2))+'</pre>')
 else:body+='<p>Source-copy integrity and the three new-value control trajectories are under review.</p>'
 extra=[r for r in d['summaries'] if r['stage'] in ['event_reader','source_reader_development']]
 body+='</section><section id="interpretation"><h2>6. Selecting evidence or interpreting the current state?</h2><p>A follow-up returns to the six development questions. The same Thinking reader receives either original-source notes or the already generated event fields, which contain short owner, deadline, status and access values with a change history. Both note sets were generated by Instruct before their questions were supplied. The full transcript and reader settings remain the same. This exploratory check was added after freezing the main design.</p>'
 if extra:
  rows=[]
  for policy in ['reactive','events','linked','reactive_guided','events_guided','linked_guided']:
   rr=sorted([r for r in extra if r['policy']==policy and r['questions']==6],key=lambda r:r['seed'])
   if not rr:continue
   rows.append([NAMES[policy],'; '.join(score(r) for r in rr),'; '.join(fmt(r['mean_request_thinking_tokens']) for r in rr),fmt(rr[0]['earlier_generated_tokens']),'; '.join(fmt(r['total_generated_tokens']) for r in rr)])
  body+=table('Matched six-question Thinking-reader check; paired values list seeds 23 and 47. Earlier writing counts once for each condition.', ['Content and prompt','Complete / 6','Mean request thinking','Earlier generated','Total generated'],rows)
 if (P/'analysis-notes.json').exists():body+=''.join('<p>'+e(x)+'</p>' for x in json.loads((P/'analysis-notes.json').read_text()).get('interpretation',[]))
 body+='</section><section id="examples"><h2>7. Inspect actual answers</h2><p>Choose a test and condition to inspect native final answers, references, review reasons and source evidence.</p><div class="filters"><label>Test <select id="stage-filter"><option value="all">All tests</option>'+''.join('<option value="'+e(s)+'">'+e(STAGES.get(s,s))+'</option>' for s in sorted({a['stage'] for a in d['answers']}))+'</select></label> <label>Condition <select id="policy-filter"><option value="all">All conditions</option>'+''.join('<option value="'+e(s)+'">'+e(NAMES.get(s,s))+'</option>' for s in sorted({a['policy'] for a in d['answers']}))+'</select></label></div><p id="example-count" class="small"></p><p><button type="button" id="previous-cases">Previous 12</button> <button type="button" id="next-cases">Next 12</button></p>'
 for a in d['answers']:
  title=STAGES.get(a['stage'],a['stage'])+' · '+NAMES.get(a['policy'],a['policy'])+' · seed '+str(a['seed'])+' · '+a['question'];content='<p><strong>Reference:</strong> '+e(a['reference_answer'])+'</p>'+text(a['answer'] or '[No complete final answer]')+'<p class="small">Request thinking: '+fmt(a['request_thinking_tokens'])+'; input: '+fmt(a['request_input_tokens'])+'; saved-note entries: '+str(a['note_entries'])+'; exact repeated fact texts: '+str(a['repeated_note_entries'])+'.</p><p><strong>Missing information:</strong> '+e((a.get('missing_information') if isinstance(a.get('missing_information'),str) else json.dumps(a.get('missing_information'),ensure_ascii=False)) or 'None stated')+'</p>'
  content+=details('Original source evidence','<ul>'+''.join('<li>'+e(x['id'])+' · '+e(x['speaker'])+': '+e(x['text'])+'</li>' for x in a['source_evidence'])+'</ul>')
  if a['review']:content+='<p><strong>'+e(a['review']['grade'].title())+':</strong> '+e(a['review']['reason'])+'</p>'
  body+='<details id="answer-'+hashlib.sha256((a['job']+'|'+a['id']).encode()).hexdigest()[:12]+'" class="answer-case" data-stage="'+e(a['stage'])+'" data-policy="'+e(a['policy'])+'"><summary>'+e(title)+'</summary>'+content+'</details>'
 body+='<p>'+link('../research/notes-optimization/question-inputs.json','Input transcripts and requests')+' · '+link('../research/notes-optimization/call-examples.json','Selected complete model calls, including reasoning text')+' · '+link('../research/notes-optimization/results.json','All answer and token records')+'</p></section>'
 body+='<section id="development"><h2>Appendix A. Development and selection</h2><p>Repeated snapshots enlarged the reader input without consistently adding facts. Compact replacement and incremental edits reduced copying, but generated prose could merge tasks, invent a field value or retain an old deadline. Source-only storage was selected because it preserved critical evidence while reducing writer output.</p><p>On the six development questions, the selected source notes reduced earlier generated tokens from 29,735 to 11,187, including seven revision checks, and earlier input tokens from 271,613 to 165,279. Instruct improved from four to five complete answers. The latest outreach time was present in the notes, yet the reader still answered with the older end-of-week time. Source retention and successful use are evaluated separately.</p>'
 body+=details('Development answer and cost table',table('Development conditions; prompt changes were chosen using these six questions. The decoder-constraint failure is excluded from policy ranking.', ['Test','Reader / seed','Condition','Complete','Mean request thinking','Earlier generated','Total generated'],[[e(STAGES.get(r['stage'],r['stage'])),e(r['model'])+' / '+str(r['seed']),e(NAMES.get(r['policy'],r['policy'])),score(r) if r['valid_policy_comparison'] else 'Excluded: decoder constraints',fmt(r['mean_request_thinking_tokens']),fmt(r['earlier_generated_tokens']),fmt(r['total_generated_tokens'])] for r in d['summaries'] if not r['stage'].startswith(('additional','parakeet','whisper'))]))
 body+=details('Implementation corrections','<ul><li>An early edit run applied the last task’s allowed-source schema to the entire batch; it is excluded from policy comparisons.</li><li>The corrected controller assigns stable IDs and validates each task against its own source IDs.</li><li>Source notes are bounded in the model input; the complete source and relationship archive remains available for auditing.</li><li>One A100 startup failed while binding a distributed communication address; single-node loopback networking resolved it.</li></ul>')
 body+=details('Selected final note states',''.join(details(s['meeting']+' · '+f"{s['source_cutoff']:.1f} s",'<pre>'+e(json.dumps(s['state'],ensure_ascii=False,indent=2))+'</pre>') for r in d['states'] if r['stage'] in ['linked_context','additional_writer'] for s in r['final_states']))+'</section>'
 body+='<section id="literature"><h2>Appendix B. Literature and design choices</h2><p>The papers support explicit updates, selective storage, source records and temporal relationships. Most use retrieval or learned memory; their reported gains do not directly establish reduced native thinking with the full transcript retained.</p>'
 body+=table('Verified primary sources and their relevance to this study.', ['Paper','Publication','Method','Design implication'],[[link(x['source'],x['title']),e(x['venue']),e(x['method']),e(x['relevance'])] for x in d['literature']['papers']])+details('Literature gaps and full review','<ul>'+''.join('<li>'+e(x['statement'])+'</li>' for x in d['literature']['gaps'])+'</ul><p>'+link('../research/notes-optimization/LITERATURE.md','Full review')+'</p>')+'</section>'
 body+='<section id="prompts"><h2>Appendix C. Exact prompts and resources</h2>'+details('Selected source-selection prompt','<pre>'+e(pr['selected_writer'])+'</pre>')+details('Revision-check prompt','<pre>'+e(pr['revision_checker'])+'</pre>')+details('Focused reader instruction','<pre>'+e(pr['reader_addendum'])+'</pre>')+details('Output schemas','<pre>'+e(json.dumps({k:pr[k] for k in ['selected_schema','revision_checker_schema']},ensure_ascii=False,indent=2))+'</pre>')+details('Earlier replacement and edit prompts',''.join(details(v['name'],'<pre>'+e(v['replacement'])+'\n\n'+e(v['edits'])+'</pre>') for v in pr['development_versions']))
 body+=details('GPU allocation and execution record','<p>Each job uses one 80 GB GPU: H100 for early development and A100 for the selected design and transfer tests. Text weights and an 8 GiB KV cache share GPU 0; writer, revision checker and reader execute sequentially through vLLM with CUDA graphs and prefix caching. Reader-only jobs consume frozen notes. No S1, TTS or ASR service shares a GPU. At most two experiment GPUs are active; each transfer reader depends on its saved writer outputs.</p><p>Recorded allocation: '+f"{d['total_allocation_GPU_hours']:.3f}"+' GPU h, including failed allocated startup; unallocated cancellation costs zero GPU h.</p>'+table('Actual run status and allocation; process completion is separate from source-reviewed accuracy.', ['Test','Reader','GPU','State','Answers','GPU h'],[[e(STAGES.get(r['stage'],r['stage'])),e(r['model']),e(r['GPU_type_VRAM']),e(r['status']),str(r['answers']),f"{r['allocation_GPU_hours']:.4f}" if r['allocation_GPU_hours'] is not None else 'Pending'] for r in d['resources']]))+'<p>'+link('../research/notes-optimization/prompts.json','Machine-readable prompts and schemas')+'</p></section>'
 nexts=json.loads((P/'analysis-notes.json').read_text()).get('next',[]) if (P/'analysis-notes.json').exists() else ['Complete the frozen transfer tests to measure answer quality and request-time reasoning.','Inspect the event trajectories to check whether revisions and unresolved states survive.','Use the paired results to choose the next full-set evaluation.']
 body+='<section id="next"><h2>Next steps and goals</h2><ul>'+''.join('<li>'+e(t)+'</li>' for t in nexts)+'</ul></section>'
 js="let casePage=0;const pageSize=12;const stage=document.getElementById('stage-filter'),policy=document.getElementById('policy-filter');function matches(){return [...document.querySelectorAll('.answer-case')].filter(x=>(stage.value==='all'||x.dataset.stage===stage.value)&&(policy.value==='all'||x.dataset.policy===policy.value));}function filter(){const all=matches();casePage=Math.max(0,Math.min(casePage,Math.ceil(all.length/pageSize)-1));document.querySelectorAll('.answer-case').forEach(x=>x.hidden=true);all.slice(casePage*pageSize,(casePage+1)*pageSize).forEach(x=>x.hidden=false);document.getElementById('example-count').textContent=all.length?((casePage*pageSize+1)+'–'+Math.min((casePage+1)*pageSize,all.length)+' of '+all.length+' answers'):'No answers in this selection';document.getElementById('previous-cases').disabled=casePage===0;document.getElementById('next-cases').disabled=(casePage+1)*pageSize>=all.length;}function reveal(){const t=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(!t)return;if(t.classList.contains('answer-case')){stage.value=t.dataset.stage;policy.value=t.dataset.policy;casePage=Math.floor(matches().indexOf(t)/pageSize);filter();}for(let p=t;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;requestAnimationFrame(()=>{const h=document.querySelector('.site-nav').getBoundingClientRect().height;window.scrollTo({top:Math.max(0,t.getBoundingClientRect().top+scrollY-h-16),behavior:'instant'});});}document.querySelectorAll('select').forEach(x=>x.addEventListener('change',()=>{casePage=0;filter();}));document.getElementById('previous-cases').onclick=()=>{casePage--;filter();};document.getElementById('next-cases').onclick=()=>{casePage++;filter();};addEventListener('load',()=>{stage.value='additional_reader';policy.value='linked_guided';filter();reveal();});addEventListener('hashchange',reveal);"
 extra='.plot-scroll{max-width:100%;overflow-x:auto}.filters{display:flex;gap:1rem;flex-wrap:wrap}.filters label{display:flex;gap:.5rem;align-items:center}.filters select{max-width:100%;padding:.4rem}.filters>label{max-width:100%}.answer-case[hidden]{display:none}figure{margin:1.5rem 0}figcaption{font-size:.92rem;color:var(--muted)}'
 page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="Source-grounded structured-note experiments for token efficiency and tracking meeting changes."><title>Structured-note optimization · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css"><style>'+CSS+extra+'</style></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><div class="container collection-nav">'+experiment_subtabs('notes')+'</div><main id="main" class="container results">'+body+'</main><script>'+js+'</script></body></html>\n';(ROOT/'experiments/structured-notes.html').write_text(page)
if __name__=='__main__':main()
